            color = "<color=#ffffff>%s</color>"
        end
        local str = string.format("%s/%s",numData.leaveNum,numData.totalNum)
        str = string.format(color,str)
        CfUtils.FillText(self.takeOutNum,str)
        --GameUtils.BindRedPoint(Constants.RedPointConst.MaidCafeTakeOutNormal, self.ButtonSaleOut, true)
    end

    self._behaviourAction = CfUtils.GetOrAddComponent(self.controller, BehaviourAction)
    self._behaviourAction.UpdateAction = function()
        self:OnFixUpdate()
    end
end

