function UIActionPrimaryMapDialog:FillCatCar()
    local targetGo = self._mapGo.transform:Find("CatCarFGo")
    if targetGo then
        local tagetPos = targetGo.transform.position
        local pos = CfUtils.WorldPosition2UIPosition(tagetPos, self.NodePar, self._mapCam)
        self._catCarFPos = Vector3(pos.x, pos.y, 0)
    end
    targetGo = self._mapGo.transform:Find("CatCarTGo")
    if targetGo then
        local tagetPos = targetGo.transform.position
        local pos = CfUtils.WorldPosition2UIPosition(tagetPos, self.NodePar, self._mapCam)
        self._catCarTPos = Vector3(pos.x, pos.y, 0)
    end
    self.CatCar.transform.localPosition = Vector3(self._catCarFPos.x, self._catCarFPos.y, 0)
    CfUtils.SetActive(self.CatCar, true)

    local sysTemId = Constants.SystemToggleIds.Id3004
    local isUnlock = GameUtils.IsUnlockedBySystemTogId(sysTemId)
    CfUtils.SetActive(self.CatCarClose, not isUnlock)
    CfUtils.SetActive(self.CatCarOpen, isUnlock)

    ---@type MaidCoffeePlayerComponent
    local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)

    local redGo = GameUtils.GetRedPointGo(self.CatCarOpen)
    if redGo then
        local redPoint = maidCoffeePlayerComponent:IsShowVipOrderRedPoint()
        GameUtils.SetRedPointNum(Constants.RedPointConst.MaidCafeTakeOutVipOrder, redPoint and 1 or 0)
        KTool.SetActive(redGo,redPoint)
    end

    local orderId, freshTime = maidCoffeePlayerComponent:GetVipOrderTime()
    if isUnlock and checkNumber(orderId) > 0 then
        self._moveTime = self:GetAllTime() - freshTime
    else
        self._moveTime = 0
    end
    self._isCanMove = checkNumber(orderId) > 0 and checkNumber(freshTime) > 0
    SetButtonAction(self.CatCarRoot, function()
        local sysTemId = Constants.SystemToggleIds.Id3004
        local isUnlock = GameUtils.IsUnlockedBySystemTogId(sysTemId)
        if not isUnlock then
            local err = GameUtils.GetUnlockDescrBySystemTogId(sysTemId)
            GameUtils.Toast(err)
            return
        end

        UIModule.OpenDialog({ id = Constants.UITypeIds.TakeoutVipOrderDialog, parameters = { } }, {
            { id = Constants.UITypeIds.UIActionPrimaryMapDialog }
        })
    end)
end

function UIActionPrimaryMapDialog:GetCarPos()
    if self._moveTime < self:GetDurTime(Status.Go) and self._moveTime > 0 then
        self._carStatus = Status.Go
    elseif self._moveTime > (self:GetDurTime(Status.Go) + self:GetDurTime(Status.Wait)) and self._moveTime < self:GetAllTime() then
        self._carStatus = Status.Back
    elseif self._moveTime >= self:GetDurTime(Status.Go) and self._moveTime <= (self:GetDurTime(Status.Go) + self:GetDurTime(Status.Wait)) then
        self._carStatus = Status.Wait
    else
        self._carStatus = Status.None
    end

    local pos
    if self._carStatus == Status.None then
        return self._catCarFPos
    elseif self._carStatus == Status.Wait then
        return self._catCarTPos
    end

    if self._carStatus == Status.Go then
        pos = Vector3.Lerp(self._catCarFPos, self._catCarTPos, self._moveTime / self:GetDurTime(Status.Go))
    elseif self._carStatus == Status.Back then
        pos = Vector3.Lerp(self._catCarTPos, self._catCarFPos, (self._moveTime - self:GetDurTime(Status.Back) - self:GetDurTime(Status.Wait)) / self:GetDurTime(Status.Back))
    end
    return pos
end

function UIActionPrimaryMapDialog:GetAllTime()
    return self:GetDurTime(Status.Go) + self:GetDurTime(Status.Wait) + self:GetDurTime(Status.Back)
end

function UIActionPrimaryMapDialog:GetDurTime(status)
    ---@type MaidCoffeePlayerComponent
    local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    local orderId, _ = maidCoffeePlayerComponent:GetVipOrderTime()
    local tableFile = SettingMgr:GetInstance():Get(AutoIds.IdSetting3054)
    local tableFileRow = tableFile:GetByPrimaryKey(orderId)
    local time = checkNumber(tableFileRow:Get("time"))

    if status == Status.Go then
        local vo = MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(33)
        return checkNumber(vo.num) * time --3.5 *3600
    elseif status == Status.Back then
        local vo = MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(35)
        return checkNumber(vo.num) * time --3.5 *3600
    elseif status == Status.Wait then
        local vo = MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(34)
        return checkNumber(vo.num) * time --1 * 3600
    end
    return 0
end

function UIActionPrimaryMapDialog:OnFixUpdate()
    self._moveTime = self._moveTime + CS.UnityEngine.Time.deltaTime
    if not self._isCanMove then
        return
    end
    self.CatCar.transform.localPosition = self:GetCarPos()
    if self._carStatus ~= Status.None then
        CfUtils.SetActive(self.CatCarCountdown, true)
        ---@type MaidCoffeePlayerComponent
        local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
        local _, freshTime = maidCoffeePlayerComponent:GetVipOrderTime()
        CfUtils.FillText(self.CatCarTimeTxt, CfUtils.GetTimeHMS(checkNumber(freshTime)))
        CfUtils.SetActive(self._carGoEffect, self._carStatus == Status.Go)
        CfUtils.SetActive(self._carBackEffect, self._carStatus == Status.Back)
    else
        CfUtils.SetActive(self.CatCarCountdown, false)
        CfUtils.SetActive(self._carGoEffect, false)
        CfUtils.SetActive(self._carBackEffect, false)
    end
end

--爬塔
function UIActionPrimaryMapDialog:FillTower()
    local sysTemId = Constants.SystemToggleIds.Id2016
    local go = self.OtherPoints.transform:Find("ActionPrimaryMapPointNode" .. sysTemId)
    CfUtils.SetActive(go, true)

    GameUtils.BindRedPoint(Constants.RedPointConst.Tower, go, true)

    self:RefreshPos(go, {
        id = sysTemId
    })

    local isUnlock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id2016)
    CfUtils.SetActive(go.transform:Find("Root/Close"), not isUnlock)
    CfUtils.SetActive(go.transform:Find("Root/Open"), isUnlock)

    local nodeGo = self._mapGo.transform:Find("AreaMap_01_plane/AreaMap_" .. sysTemId)
    if not isNull(nodeGo) then
        local quickTap = CfUtils.GetOrAddComponent(nodeGo, QuickTap)
        if not isNull(quickTap) then
            quickTap.onTap:RemoveAllListeners()
            quickTap.onTap:AddListener(function()
                if not self.controller or not self.controller.HasFocus then
                    return
                end
                if not isUnlock then
                    local err = GameUtils.GetUnlockDescrBySystemTogId(Constants.SystemToggleIds.Id2016)
                    GameUtils.Toast(err)
                    return
                end

                UIModule.OpenDialog({ id = Constants.UITypeIds.UIOverseaTowerEntryDialog, parameters = {} }, {
                    { id = Constants.UITypeIds.UIActionPrimaryMapDialog }
                })
            end)
        end
    end
end

--混沌回忆
function UIActionPrimaryMapDialog:FillChaoticRecall()
    local sysTemId = Constants.SystemToggleIds.Id2019
    local go = self.OtherPoints.transform:Find("ActionPrimaryMapPointNode" .. sysTemId)
    local vo = CfUtils.SystemToggleVo( sysTemId)
    --如果是关闭
    if checkNumber(vo.switch) == Constants.ModelFunctionSwitch.Off then
        CfUtils.SetActive(go, false)
        return
    end

    CfUtils.SetActive(go, true)

    GameUtils.BindRedPoint(Constants.RedPointConst.QuestChaoticRecall, go, true)

    self:RefreshPos(go, {
        id = sysTemId
    })

    local isUnlock = GameUtils.IsUnlockedBySystemTogId(sysTemId)
    CfUtils.SetActive(go.transform:Find("Root/Close"), not isUnlock)
    CfUtils.SetActive(go.transform:Find("Root/Open"), isUnlock)
    
    local destroyGo = go.transform:Find("Root/Open/DestroyGroup")
    local playerDojo = GameUtils.GetPlayerDojo()
    if isNotNull(destroyGo) then
        if isUnlock and playerDojo:IsOpenActionDark() then
            local node = CfUtils.GetLuaScr(destroyGo,"Game.Behaviours.CommonMarqueeNode")
            if node then
                node:Refresh(localize("噩梦回响挑战关卡开启中....."))
            end
            CfUtils.SetActive(destroyGo.gameObject,true)
        else
            CfUtils.SetActive(destroyGo.gameObject,false)
        end
    end
    
    local nodeGo = self._mapGo.transform:Find("AreaMap_01_plane/AreaMap_" .. sysTemId)
    if not isNull(nodeGo) then
        local quickTap = CfUtils.GetOrAddComponent(nodeGo, QuickTap)
        if not isNull(quickTap) then
            quickTap.onTap:RemoveAllListeners()
            quickTap.onTap:AddListener(function()
                if not self.controller or not self.controller.HasFocus then
                    return
                end
                if not isUnlock then
                    local err = GameUtils.GetUnlockDescrBySystemTogId(sysTemId)
                    GameUtils.Toast(err)
                    return
                end

                UIModule.OpenDialog({ id = Constants.UITypeIds.ActionDarkDreamMainDialog, parameters = {} }, {
                    { id = Constants.UITypeIds.UIActionPrimaryMapDialog }
                })
                GameUtils.SetRedPointNum(Constants.RedPointConst.QuestChaoticNewRecall, 0)
            end)
        end
    end
end

