function UIActionPrimaryMapDialog:FillHeadInfo(go, data)
    if not go or not data then
        return
    end
    local t = CfUtils.Split(data.infoCoordinate)
    --self:RefreshPos(go, data)

    go.transform:GetComponent(typeof(RectTransform)).anchoredPosition = Vector3(t[1], t[2], t[3])

    CfUtils.FillImage(go.transform:Find("AnimRoot/ImgIcon1"), data.regionSpec)
    CfUtils.FillImage(go.transform:Find("AnimRoot/ImgIcon2"), data.regionSpec)
    CfUtils.SetActive(go, true)
end

function UIActionPrimaryMapDialog:RefreshPos(go, data)
    if not go or not data then
        return
    end

    local targetGo = self._mapGo.transform:Find(data.id)
    if not targetGo then
        return
    end
    local tagetPos = targetGo.transform.position
    local pos = CfUtils.WorldPosition2UIPosition(tagetPos, self.NodePar, self._mapCam)
    go.transform.localPosition = Vector3(pos.x, pos.y, 0)  --ActionUtils.GetPos(data.id)
end

