---@param go UnityEngine.Transform
---@param data RegionPrimaryMapVo
function UIActionPrimaryMapDialog:FillPoint(go, data)
    if not go or not data then
        return
    end

    self:RefreshPos(go, data)
    CfUtils.SetActive(go, true)

    ---@type UIActionPrimaryMapNode
    local scr = CfUtils.GetLuaScr(go, ActionPrimaryMapNodePath)
    local nodeGo = self._mapGo.transform:Find("AreaMap_01_plane/AreaMap_" .. data.id)
    if not isNull(nodeGo) then
        local isUnlock, err = ActionUtils.IsUnlockRegionalPoint(data.id)
        local quickTap = CfUtils.GetOrAddComponent(nodeGo, QuickTap)
        if not isNull(quickTap) then
            quickTap.onTap:RemoveAllListeners()
            quickTap.onTap:AddListener(function()
                if not self.controller or not self.controller.HasFocus then
                    return
                end
                if not isUnlock then
                    GameUtils.Toast(err)
                    return
                end
                if self._isIntroMode then
                    local encyDojo = illustratedHandbookComp:GetRegionMapEncyDojoMap()[tostring(data.id)]
                    -- clear newMark
                    if encyDojo.isNewMark then
                        illustratedHandbookComp:ClearRegionMapEncyNewMark(data.id)
                        if scr then
                            scr:SwitchNewMark(false)
                        end
                    end
                    CfUtils.DialogOpen(Constants.UITypeIds.IllustratedHandbookAreaIntroDialog, { regionId = data.id })
                    return
                end
                CfUtils.SetTopActive(false)
                CfUtils.SetActive(self.controller.gameObject, false)
                CfUtils.SetActive(nodeGo.transform:Find("click"), true)
                RegionQuestMgr:GetInstance():PlayPrimaryMapCrossFadeToSecond(data.id, function()
                    UIModule.OpenDialog({ id = Constants.UITypeIds.UIActionSecondMapDialog, parameters = { id = data.id } }, {
                        { id = Constants.UITypeIds.UIActionPrimaryMapDialog }
                    })
                end)
            end)
        end

        local sr = CfUtils.GetOrAddComponent(nodeGo, SpriteRenderer)
        if sr then
            local color = isUnlock and XLuaUtils.HexToColor('#FFFFFF') or XLuaUtils.HexToColor('#BCBCBC')
            sr.color = color
        end

        CfUtils.SetActive(nodeGo.transform:Find("lock"), not isUnlock)
    end

    if scr then
        scr.isIntroMode = self._isIntroMode
        scr:Refresh(data, function()
        end)
    end
end

