--外卖
function UIActionPrimaryMapDialog:OnButtonSaleOut()
    local isUnlock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id3003)
    if not isUnlock then
        local err = GameUtils.GetUnlockDescrBySystemTogId(Constants.SystemToggleIds.Id3003)
        GameUtils.Toast(err)
        return
    end
    local time = os.time()
    local t = timestamp_to_time(time)
    CfUtils.WriteLocalData("ButtonSaleOutClickTime", checkNumber(t.day))
    UIModule.OpenDialog({ id = Constants.UITypeIds.UIMaidCoffeeTakeoutDialog, parameters = {} }, {{id = Constants.UITypeIds.UIActionPrimaryMapDialog}})
end

function UIActionPrimaryMapDialog:OnBackAction()
    KTool.SetActive(self.Root.gameObject, false)
end

function UIActionPrimaryMapDialog:OnInitialize()
    return CoWaitDo(function()
        local initParams = self.controller.Argument.parameters or {}
        self._isIntroMode = checkBool(initParams.introMode)

        --CfUtils.SetUICameraProjection(true)
        self._mapGo = RegionQuestMgr:GetInstance():GetPrimaryMapGo()

        local isFinish = false
        Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)
        ActionComponent:OverseaRegionalHomeReq(function()
            isFinish = true
        end)

        self._mapCam = self._mapGo.transform:Find("AreaMap_01_Camera").gameObject:GetComponent(typeof(Camera))

        self._carGoEffect = self._mapGo.transform:Find("AreaMap_01_plane/CatCar_Transit/UIFX_CatCar_Go")
        self._carBackEffect = self._mapGo.transform:Find("AreaMap_01_plane/CatCar_Transit/UIFX_CatCar_Return")

        while not isFinish do
            CoYield()
        end

        local parGo = self._mapGo.transform:Find("ParticleSystem")
        if not isNull(parGo) then
            CfUtils.SetActive(parGo, false)
        end

        self:InitData()
        self:FillSelf()
    end)
end

function UIActionPrimaryMapDialog:OnFinalize()
    return CoWaitDo(function()
        RegionQuestMgr:GetInstance():ClearPrimaryMapGo()
        if self._behaviourAction then
            self._behaviourAction.UpdateAction = nil
            self._behaviourAction = nil
        end

        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.PhoneFishCollection)
--[[        local pointNum = 0
        for k, v in pairs(self._allPoints) do
            if ActionUtils.IsShowMapRedpoint(v.id) or ActionUtils.IsHasTaskCanDraw(v.id) then
                pointNum = 1
            end
        end
        local num = GameUtils.GetRedPointNum(Constants.RedPointConst.Quest)
        if pointNum ~= num then
            GameUtils.SetRedPointNum(Constants.RedPointConst.Quest, pointNum)
        end]]

        --GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.MaidCafeTakeOutNormal)
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.Tower)
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end)
end

return UIActionPrimaryMapDialog
